  echo "[*] Building linux/amd64 ..."
  GOOS=linux GOARCH=amd64 go build -o aquatone ..
}

build_linux_arm64() {
  echo "[*] Building linux/arm64 ..."
  GOOS=linux GOARCH=arm go build -o aquatone ..
}

build_macos_amd64() {
