package agents

import (
	"context"
	"fmt"
	"io/ioutil"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/michenriksen/aquatone/core"
)

type URLScreenshotter struct {
	session            *core.Session
	chromePath         string
	tempUserDirPath    string
	screenshotSlots    chan struct{}
	runScreenshot      func(context.Context, *core.Page, string) (bool, error)
	dedupMutex         sync.Mutex
	dedupedScreenshots map[string]struct{}
	rateMutex          sync.Mutex
	nextScreenshotAt   time.Time
}

func NewURLScreenshotter() *URLScreenshotter {
	return &URLScreenshotter{}
}

func (a *URLScreenshotter) ID() string {
	return "agent:url_screenshotter"
}

func (a *URLScreenshotter) Register(s *core.Session) error {
	s.EventBus.SubscribeAsync(core.URLResponsive, a.OnURLResponsive, false)
	s.EventBus.SubscribeAsync(core.SessionEnd, a.OnSessionEnd, false)
	a.session = s
	a.createTempUserDir()
	a.locateChrome()
	a.initializeScheduler()

	return nil
}

func (a *URLScreenshotter) OnURLResponsive(url string) {
	a.session.Out.Debug("[%s] Received new responsive URL %s\n", a.ID(), url)
	page := a.session.GetPage(url)
	if page == nil {
		a.session.Out.Error("Unable to find page for URL: %s\n", url)
		return
	}

	filename := page.BaseFilename()
	if filename == "" {
		filename = url
	}

	a.dedupMutex.Lock()
	if a.dedupedScreenshots == nil {
		a.dedupedScreenshots = make(map[string]struct{})
	}
	if _, found := a.dedupedScreenshots[filename]; found {
		a.dedupMutex.Unlock()
		a.session.Stats.IncrementScreenshotDeduped()
		a.session.Out.Debug("[%s] Skipping duplicate screenshot for %s\n", a.ID(), url)
		return
	}
	a.dedupedScreenshots[filename] = struct{}{}
	a.dedupMutex.Unlock()

	a.session.WaitGroup.Add()
	go func(page *core.Page) {
		defer a.session.WaitGroup.Done()
		a.screenshotPage(page)
	}(page)
}

func (a *URLScreenshotter) OnSessionEnd() {
	a.session.Out.Debug("[%s] Received SessionEnd event\n", a.ID())
	os.RemoveAll(a.tempUserDirPath)
	a.session.Out.Debug("[%s] Deleted temporary user directory at: %s\n", a.ID(), a.tempUserDirPath)
}

func (a *URLScreenshotter) createTempUserDir() {
	dir, err := ioutil.TempDir("", "aquatone-chrome")
	if err != nil {
		a.session.Out.Fatal("Unable to create temporary user directory for Chrome/Chromium browser\n")
		os.Exit(1)
	}
	a.session.Out.Debug("[%s] Created temporary user directory at: %s\n", a.ID(), dir)
	a.tempUserDirPath = dir
}

func (a *URLScreenshotter) initializeScheduler() {
	a.dedupedScreenshots = make(map[string]struct{})
	a.screenshotSlots = make(chan struct{}, a.screenshotConcurrency())
	a.runScreenshot = a.runChromeScreenshot
}

func (a *URLScreenshotter) screenshotConcurrency() int {
	if a.session.Options.ScreenshotThreads != nil && *a.session.Options.ScreenshotThreads > 0 {
		return *a.session.Options.ScreenshotThreads
	}
	if a.session.Options.Threads != nil && *a.session.Options.Threads > 0 {
		return *a.session.Options.Threads
	}
	return 1
}

func (a *URLScreenshotter) locateChrome() {
	if *a.session.Options.ChromePath != "" {
		a.chromePath = *a.session.Options.ChromePath
		return
	}

	paths := []string{
		"/usr/bin/google-chrome",
		"/usr/bin/google-chrome-beta",
		"/usr/bin/google-chrome-unstable",
		"/usr/bin/chromium-browser",
		"/usr/bin/chromium",
		"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
		"/Applications/Google Chrome Canary.app/Contents/MacOS/Google Chrome Canary",
		"/Applications/Chromium.app/Contents/MacOS/Chromium",
		"C:/Program Files (x86)/Google/Chrome/Application/chrome.exe",
	}

	for _, path := range paths {
		if _, err := os.Stat(path); os.IsNotExist(err) {
			continue
		}
		a.chromePath = path
	}

	if a.chromePath == "" {
		a.session.Out.Fatal("Unable to locate a valid installation of Chrome. Install Google Chrome or try specifying a valid location with the -chrome-path option.\n")
		os.Exit(1)
	}

	if strings.Contains(strings.ToLower(a.chromePath), "chrome") {
		a.session.Out.Warn("Using unreliable Google Chrome for screenshots. Install Chromium for better results.\n\n")
	} else {
		out, err := exec.Command(a.chromePath, "--version").Output()
		if err != nil {
			a.session.Out.Warn("An error occurred while trying to determine version of Chromium.\n\n")
			return
		}
		version := string(out)
		re := regexp.MustCompile(`(\d+)\.`)
		match := re.FindStringSubmatch(version)
		if len(match) <= 0 {
			a.session.Out.Warn("Unable to determine version of Chromium. Screenshotting might be unreliable.\n\n")
			return
		}
		majorVersion, _ := strconv.Atoi(match[1])
		if majorVersion < 72 {
			a.session.Out.Warn("An older version of Chromium is installed. Screenshotting of HTTPS URLs might be unreliable.\n\n")
		}
	}

	a.session.Out.Debug("[%s] Located Chrome/Chromium binary at %s\n", a.ID(), a.chromePath)
}

func (a *URLScreenshotter) screenshotPage(page *core.Page) {
	filePath := fmt.Sprintf("screenshots/%s.png", page.BaseFilename())

	a.waitForRateLimit()
	if a.screenshotSlots != nil {
		a.screenshotSlots <- struct{}{}
		defer func() { <-a.screenshotSlots }()
	}

	runScreenshot := a.runScreenshot
	if runScreenshot == nil {
		runScreenshot = a.runChromeScreenshot
	}

	ctx, cancel := context.WithTimeout(context.Background(), time.Duration(*a.session.Options.ScreenshotTimeout)*time.Millisecond)
	defer cancel()

	timedOut, err := runScreenshot(ctx, page, a.session.GetFilePath(filePath))
	if err != nil {
		a.session.Stats.IncrementScreenshotFailed()
		a.session.Out.Debug("[%s] Error: %v\n", a.ID(), err)
		if timedOut {
			a.session.Out.Error("%s: screenshot timed out\n", page.URL)
			return
		}

		a.session.Out.Error("%s: screenshot failed: %s\n", page.URL, err)
		return
	}

	a.session.Stats.IncrementScreenshotSuccessful()
	a.session.Out.Info("%s: %s\n", page.URL, Green("screenshot successful"))
	page.ScreenshotPath = filePath
	page.HasScreenshot = true
}

func (a *URLScreenshotter) runChromeScreenshot(ctx context.Context, page *core.Page, screenshotPath string) (bool, error) {
	userDataDir, err := ioutil.TempDir(a.tempUserDirPath, "profile-")
	if err != nil {
		return false, err
	}
	defer os.RemoveAll(userDataDir)

	var chromeArguments = []string{
		"--headless", "--disable-gpu", "--hide-scrollbars", "--mute-audio", "--disable-notifications",
		"--no-first-run", "--disable-crash-reporter", "--ignore-certificate-errors", "--incognito",
		"--disable-infobars", "--disable-sync", "--no-default-browser-check",
		"--user-data-dir=" + userDataDir,
		"--user-agent=" + RandomUserAgent(),
		"--window-size=" + *a.session.Options.Resolution,
		"--screenshot=" + screenshotPath,
	}

	if os.Geteuid() == 0 {
		chromeArguments = append(chromeArguments, "--no-sandbox")
	}

	if *a.session.Options.Proxy != "" {
		chromeArguments = append(chromeArguments, "--proxy-server="+*a.session.Options.Proxy)
	}

	chromeArguments = append(chromeArguments, page.URL)

	cmd := exec.CommandContext(ctx, a.chromePath, chromeArguments...)
	if err := cmd.Start(); err != nil {
		a.killChromeProcessIfRunning(cmd)
		return false, err
	}

	if err := cmd.Wait(); err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			a.killChromeProcessIfRunning(cmd)
			return true, err
		}

		a.killChromeProcessIfRunning(cmd)
		return false, err
	}

	a.killChromeProcessIfRunning(cmd)
	return false, nil
}

func (a *URLScreenshotter) waitForRateLimit() {
	if a.session.Options.ScreenshotRate == nil || *a.session.Options.ScreenshotRate == 0 {
		return
	}

	if delay := a.reserveRateSlot(time.Now()); delay > 0 {
		time.Sleep(delay)
	}
}

func (a *URLScreenshotter) reserveRateSlot(now time.Time) time.Duration {
	if a.session.Options.ScreenshotRate == nil || *a.session.Options.ScreenshotRate <= 0 {
		return 0
	}

	interval := time.Second / time.Duration(*a.session.Options.ScreenshotRate)
	a.rateMutex.Lock()
	defer a.rateMutex.Unlock()

	if a.nextScreenshotAt.IsZero() || !a.nextScreenshotAt.After(now) {
		a.nextScreenshotAt = now
	}

	delay := a.nextScreenshotAt.Sub(now)
	a.nextScreenshotAt = a.nextScreenshotAt.Add(interval)
	return delay
}

func (a *URLScreenshotter) killChromeProcessIfRunning(cmd *exec.Cmd) {
	if cmd.Process == nil {
		return
	}
	cmd.Process.Release()
	cmd.Process.Kill()
}

package agents

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"sync"
	"testing"
	"time"

	"github.com/michenriksen/aquatone/core"
	"github.com/remeh/sizedwaitgroup"
)

func newScreenshotTestSession(t *testing.T, threads int, rate int) (*core.Session, func()) {
	t.Helper()

	outDir, err := ioutil.TempDir("", "aquatone-screenshot-test")
	if err != nil {
		t.Fatal(err)
	}

	screenshotThreads := threads
	screenshotRate := rate
	screenshotTimeout := 1000
	globalThreads := threads
	resolution := "1440,900"
	proxy := ""
	chromePath := ""

	options := core.Options{
		Threads:           &globalThreads,
		OutDir:            &outDir,
		Proxy:             &proxy,
		ChromePath:        &chromePath,
		Resolution:        &resolution,
		ScreenshotTimeout: &screenshotTimeout,
		ScreenshotThreads: &screenshotThreads,
		ScreenshotRate:    &screenshotRate,
	}

	logger := &core.Logger{}
	logger.SetSilent(true)

	session := &core.Session{
		Options: options,
		Out:     logger,
		Stats:   &core.Stats{StartedAt: time.Now()},
		Pages:   make(map[string]*core.Page),
	}
	session.WaitGroup = sizedwaitgroup.New(threads)

	cleanup := func() {
		os.RemoveAll(outDir)
	}
	return session, cleanup
}

func Test500TargetScreenshotsAreDedupedAndReportCompatible(t *testing.T) {
	const targetCount = 500
	const duplicateEvery = 10
	const screenshotThreads = 8

	session, cleanup := newScreenshotTestSession(t, screenshotThreads, 0)
	defer cleanup()

	screenshotter := NewURLScreenshotter()
	screenshotter.session = session
	screenshotter.initializeScheduler()

	var mutex sync.Mutex
	active := 0
	maxActive := 0
	screenshotCount := 0
	screenshotPaths := make(map[string]struct{})
	screenshotter.runScreenshot = func(ctx context.Context, page *core.Page, path string) (bool, error) {
		mutex.Lock()
		active++
		screenshotCount++
		if active > maxActive {
			maxActive = active
		}
		screenshotPaths[path] = struct{}{}
		mutex.Unlock()

		time.Sleep(time.Millisecond)

		mutex.Lock()
		active--
		mutex.Unlock()
		return false, nil
	}

	for i := 0; i < targetCount; i++ {
		target := fmt.Sprintf("https://target-%03d.example.com/path/%d", i, i)
		if _, err := session.AddPage(target); err != nil {
			t.Fatal(err)
		}

		screenshotter.OnURLResponsive(target)
		if i%duplicateEvery == 0 {
			screenshotter.OnURLResponsive(target)
		}
	}
	session.WaitGroup.Wait()

	mutex.Lock()
	actualCount := screenshotCount
	actualMaxActive := maxActive
	actualPathCount := len(screenshotPaths)
	mutex.Unlock()

	if actualCount != targetCount {
		t.Fatalf("took %d screenshots, want %d", actualCount, targetCount)
	}
	if actualPathCount != targetCount {
		t.Fatalf("wrote %d unique screenshot paths, want %d", actualPathCount, targetCount)
	}
	if actualMaxActive > screenshotThreads {
		t.Fatalf("maximum screenshot concurrency was %d, limit is %d", actualMaxActive, screenshotThreads)
	}
	if session.Stats.ScreenshotSuccessful != targetCount {
		t.Fatalf("successful screenshots = %d, want %d", session.Stats.ScreenshotSuccessful, targetCount)
	}
	if session.Stats.ScreenshotDeduped != targetCount/duplicateEvery {
		t.Fatalf("deduplicated screenshots = %d, want %d", session.Stats.ScreenshotDeduped, targetCount/duplicateEvery)
	}

	for _, page := range session.Pages {
		if !page.HasScreenshot || page.ScreenshotPath == "" {
			t.Fatalf("page %s is missing screenshot report metadata", page.URL)
		}
	}

	sessionJSON, err := json.Marshal(session)
	if err != nil {
		t.Fatal(err)
	}
	var restored core.Session
	if err := json.Unmarshal(sessionJSON, &restored); err != nil {
		t.Fatalf("session JSON is not readable: %v", err)
	}
	if len(restored.Pages) != targetCount {
		t.Fatalf("restored session has %d pages, want %d", len(restored.Pages), targetCount)
	}

	template, err := ioutil.ReadFile("../static/report_template.html")
	if err != nil {
		t.Fatal(err)
